static int checks=0;
void check(bool ok,const char *m){if(!ok)throw std::runtime_error(m);++checks;}
class TestPage:public ConfigPage {int *saved;QString key;public:QLineEdit *value;TestPage(int *s,QString k):ConfigPage(nullptr),saved(s),key(k){value=new QLineEdit(QSettings().value(key,"old").toString(),this);}QString title()const override{return key;}QIcon icon()const override{return {};}void applyConf()override{++*saved;QSettings().setValue(key,value->text());}};
void settingsTests(){
 int constructed=0,saved=0;QSettings().setValue("untouched","preserve");
 {ConfigDialog d;for(int i=0;i<3;++i)d.addLazyPage23(QString::number(i),{},[&,i](){++constructed;return new TestPage(&saved,QString::number(i));});
 check(constructed==0,"registering settings pages constructs none");d.setCurrentPage(1);check(constructed==1&&d.pages[0]==nullptr&&d.pages[1],"only requested settings page is built");auto *page=static_cast<TestPage*>(d.pages[1]);page->value->setText("edited");d.setCurrentPage(2);d.setCurrentPage(1);check(constructed==2&&static_cast<TestPage*>(d.pages[1])->value->text()=="edited","returning to a page retains unsaved edits");d.applyConf();check(saved==2&&QSettings().value("1")=="edited"&&!QSettings().contains("0")&&QSettings().value("untouched")=="preserve","OK saves visited pages and leaves unvisited settings untouched");}
 {ConfigDialog d;d.addLazyPage23("cancel",{},[&](){return new TestPage(&saved,"cancel");});d.setCurrentPage(0);static_cast<TestPage*>(d.pages[0])->value->setText("discard");d.reject();check(!QSettings().contains("cancel")&&saved==2,"Cancel writes no settings");}
 {ConfigDialog d;auto *first=new TestPage(&saved,"eager");d.addPage(first);d.addLazyPage23("later",{},[&](){return new TestPage(&saved,"later");});check(d.pages[0]==first,"eager project-property pages retain public index compatibility");d.setCurrentPage(1);check(d.pages[1]!=nullptr,"mixed eager/lazy pages retain indices");d.setCurrentPage(-1);d.setCurrentPage(99);check(d.pages.size()==2,"invalid page indices are harmless");}
}
void lazyLanguageTests(const QString &out){
 QETProject p;QETApp::registerProject(&p);QStringList ids;
 for(int i=0;i<5;++i){auto *page=p.addNewDiagram();auto *t=new IndependentTextItem("English description "+QString::number(i));page->addItem(t);t->setPos(100,150+i*20);ids<<t->languageId16();}
 QVariantMap d;QetLanguagesUi16::scan(&p,d);auto es=d["entries"].toMap();for(int i=0;i<ids.size();++i){auto e=es[ids[i]].toMap();e["variants"]=QVariantMap{{"de",QVariantMap{{"text","Deutsche Beschreibung "+QString::number(i)},{"x",320.0},{"y",200.0+i*20}}}};es[ids[i]]=e;}d["entries"]=es;d["activeLanguage"]="de";d["languages"]=QStringList{"en","de"};QetLanguagesUi16::apply(&p,d,false);QString error;check(p.writeContainerFile(out+"/Deferred_language_fixture.qetz",&error),qPrintable(error));
 {QETProject again(out+"/Deferred_language_fixture.qetz");QETApp::registerProject(&again);check(again.state()==QETProject::Ok,"deferred language fixture opens");const int waiting=again.unloadedFolioCount();check(waiting>0,"language restoration does not force unopened folios to load");auto captured=QetLanguagePositions21::capture(&again,again.languageData());check(again.unloadedFolioCount()==waiting,"capturing positions leaves unloaded folios untouched");auto *page=again.folios().at(3);page->ensureLoaded();check(again.unloadedFolioCount()>0,"opening one independent sheet does not build all sheets");DiagramTextItem *text=nullptr;for(auto *item:page->items())if(auto *t=dynamic_cast<DiagramTextItem*>(item))if(t->languageId16()==ids[3])text=t;check(text&&text->displayedText16()=="Deutsche Beschreibung 3","deferred sheet displays its active translation");check(text->pos()==QPointF(320,260),"deferred sheet restores saved German manual position");check(again.writeContainerFile(out+"/Deferred_language_resaved.qetz",&error),qPrintable(error));QETApp::unregisterProject(&again);}
 {QETProject again(out+"/Deferred_language_resaved.qetz");QETApp::registerProject(&again);auto texts=QetLanguagesUi16::texts(&again);for(auto *t:texts)if(ids.contains(t->languageId16())){int i=ids.indexOf(t->languageId16());check(t->displayedText16()=="Deutsche Beschreibung "+QString::number(i)&&t->pos()==QPointF(320,200+i*20),"save preserves translations and positions for every deferred sheet");}auto data=again.languageData();data["activeLanguage"]="en";QetLanguagesUi16::apply(&again,data,false);for(auto *t:texts)if(ids.contains(t->languageId16()))check(t->pos()==QPointF(100,150+ids.indexOf(t->languageId16())*20),"English source position survives deferred save");QETApp::unregisterProject(&again);}
 QETApp::unregisterProject(&p);
}

void render(Diagram *page,const QString &base){auto rect=page->border_and_titleblock.borderAndTitleBlockRect();QPdfWriter pdf(base+".pdf");pdf.setResolution(96);pdf.setPageSize(QPageSize(QPageSize::A4));pdf.setPageOrientation(QPageLayout::Landscape);QPainter p(&pdf);page->render(&p,QRectF(0,0,p.device()->width(),p.device()->height()),rect);p.end();QImage image(1800,1250,QImage::Format_ARGB32);image.fill(Qt::white);QPainter q(&image);page->render(&q,QRectF(0,0,1800,1250),rect);q.end();check(image.save(base+".png"),"sheet comparison image saved");}
